import { Sidebar } from "@/components/Sidebar";

/**
 * Wraps every `/docs/*` route with the persistent sidebar.
 *
 * `LayoutProps<"/docs">` is generated by Next.js from the folder structure and
 * is globally available — it types `children` for us. Because this is a layout,
 * the sidebar is NOT re-rendered when navigating between topics; only the page
 * slot changes.
 */
export default function DocsLayout({ children }: LayoutProps<"/docs">) {
  return (
    <div className="mx-auto flex w-full max-w-[90rem] gap-10 px-6">
      <aside className="sticky top-14 hidden h-[calc(100vh-3.5rem)] w-64 shrink-0 overflow-y-auto py-10 lg:block">
        <Sidebar />
      </aside>
      <div className="min-w-0 flex-1">{children}</div>
    </div>
  );
}
